namespace ProductsApi.Models;

public enum Category
{
    Electronics,
    Clothing,
    Food,
    Books
}

public class Product
{
    public Guid Id { get; set; }
    public required string Name { get; set; }
    public decimal Price { get; set; }
    public Category Category { get; set; }
    public DateTime CreatedAt { get; set; }
}

public class CreateProductRequest
{
    public required string Name { get; set; }
    public decimal Price { get; set; }
    public Category Category { get; set; }
}

using ProductsApi.Models;

namespace ProductsApi.Services;

public interface IProductService
{
    IReadOnlyList<Product> GetAll();
    Product? GetById(Guid id);
    Product Create(CreateProductRequest request);
}

using ProductsApi.Models;

namespace ProductsApi.Services;

public class InMemoryProductService : IProductService
{
    private readonly List<Product> _products = [];
    private readonly object _lock = new();

    public IReadOnlyList<Product> GetAll()
    {
        lock (_lock)
        {
            return _products.ToList();
        }
    }

    public Product? GetById(Guid id)
    {
        lock (_lock)
        {
            return _products.FirstOrDefault(p => p.Id == id);
        }
    }

    public Product Create(CreateProductRequest request)
    {
        var product = new Product
        {
            Id = Guid.NewGuid(),
            Name = request.Name,
            Price = request.Price,
            Category = request.Category,
            CreatedAt = DateTime.UtcNow
        };

        lock (_lock)
        {
            _products.Add(product);
        }

        return product;
    }
}

using System.Text.Json.Serialization;
using Microsoft.AspNetCore.Http.HttpResults;
using ProductsApi.Models;
using ProductsApi.Services;

var builder = WebApplication.CreateBuilder(args);

builder.Services.AddSingleton<IProductService, InMemoryProductService>();

builder.Services.ConfigureHttpJsonOptions(options =>
{
    options.SerializerOptions.Converters.Add(new JsonStringEnumConverter());
});

builder.Services.AddOpenApi();

var app = builder.Build();

app.MapOpenApi();

var products = app.MapGroup("/api/products")
    .WithTags("Products");

products.MapGet("/", (IProductService service) =>
{
    return Results.Ok(service.GetAll());
})
.WithName("GetAllProducts")
.WithSummary("List all products")
.WithDescription("Returns all products currently stored in the catalog.")
.Produces<IReadOnlyList<Product>>(StatusCodes.Status200OK);

products.MapGet("/{id:guid}", Results<Ok<Product>, NotFound> (Guid id, IProductService service) =>
{
    var product = service.GetById(id);
    return product is not null
        ? TypedResults.Ok(product)
        : TypedResults.NotFound();
})
.WithName("GetProductById")
.WithSummary("Get a product by ID")
.WithDescription("Returns a single product matching the specified unique identifier. Returns 404 if not found.")
.Produces<Product>(StatusCodes.Status200OK)
.Produces(StatusCodes.Status404NotFound);

products.MapPost("/", Results<Created<Product>, ValidationProblem> (CreateProductRequest request, IProductService service) =>
{
    if (string.IsNullOrWhiteSpace(request.Name))
    {
        return TypedResults.ValidationProblem(new Dictionary<string, string[]>
        {
            ["Name"] = ["Name is required."]
        });
    }

    if (request.Price < 0)
    {
        return TypedResults.ValidationProblem(new Dictionary<string, string[]>
        {
            ["Price"] = ["Price must be non-negative."]
        });
    }

    var product = service.Create(request);
    return TypedResults.Created($"/api/products/{product.Id}", product);
})
.WithName("CreateProduct")
.WithSummary("Create a new product")
.WithDescription("Creates a new product in the catalog. Name is required and price must be non-negative.")
.Produces<Product>(StatusCodes.Status201Created)
.ProducesValidationProblem();

app.Run();

